package store

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"time"
	"unicode/utf8"
)

const CoreBudget = 8000

var CoreScopes = []string{GlobalScope}

type BudgetError struct {
	Size   int
	Budget int
	Keys   []string
}

func (e *BudgetError) Error() string {
	return fmt.Sprintf("core records are %d chars, budget %d: shorten a core record or drop --core from one of %s",
		e.Size, e.Budget, strings.Join(e.Keys, ", "))
}

const coreHeader = "# Agent memory: core records\n\n" +
	"This file is generated by `mem core` from the store; `mem get KEY --history` shows earlier versions of a record.\n"

var kindTitles = map[Kind]string{
	Rule:     "Rules",
	State:    "State",
	Fact:     "Facts",
	Incident: "Incidents",
	Howto:    "Howtos",
	Log:      "Logs",
}

func (s *Store) coreRecords(ctx context.Context, q querier, scopes []string) ([]Record, error) {
	where := "WHERE r.core = 1 AND r.status = ?"
	args := []any{Current}
	if len(scopes) > 0 {
		sc := lowerAll(scopes)
		where += " AND EXISTS (SELECT 1 FROM scopes s WHERE s.record_id = r.id AND s.scope IN (" + placeholders(len(sc)) + "))"
		for _, v := range sc {
			args = append(args, v)
		}
	}
	rows, err := s.loadWhere(ctx, q, where+" ORDER BY r.key", args...)
	if err != nil {
		return nil, err
	}
	out := make([]Record, len(rows))
	for i, r := range rows {
		out[i] = r.rec
	}
	return out, nil
}

func (s *Store) Core(ctx context.Context, scopes []string) ([]Record, error) {
	return s.coreRecords(ctx, s.db, scopes)
}

func (s *Store) checkCore(ctx context.Context, q querier, touched bool) error {
	if !touched {
		return nil
	}
	recs, err := s.coreRecords(ctx, q, CoreScopes)
	if err != nil {
		return err
	}
	_, err = RenderCore(recs, CoreBudget)
	return err
}

func RenderRecord(r Record) string {
	var b strings.Builder
	b.WriteString("- `" + r.Key + "`")
	if r.Kind == State {
		b.WriteString(" [as of " + r.AsOf().Local().Format(time.DateOnly) + "]")
	}
	b.WriteString(": ")
	if r.Title != "" {
		b.WriteString(strings.TrimRight(r.Title, ".") + ". ")
	}
	for i, line := range strings.Split(r.Body, "\n") {
		if i > 0 {
			b.WriteString("\n")
			if line != "" {
				b.WriteString("  ")
			}
		}
		b.WriteString(line)
	}
	b.WriteString("\n")
	return b.String()
}

func RenderCore(recs []Record, budget int) (string, error) {
	sorted := slices.Clone(recs)
	order := func(k Kind) int { return slices.Index(Kinds, k) }
	slices.SortStableFunc(sorted, func(a, b Record) int {
		if d := order(a.Kind) - order(b.Kind); d != 0 {
			return d
		}
		return strings.Compare(a.Key, b.Key)
	})
	var b strings.Builder
	b.WriteString(coreHeader)
	var last Kind
	for _, r := range sorted {
		if r.Kind != last {
			b.WriteString("\n## " + kindTitles[r.Kind] + "\n\n")
			last = r.Kind
		}
		b.WriteString(RenderRecord(r))
	}
	out := b.String()
	if n := utf8.RuneCountInString(out) - utf8.RuneCountInString(coreHeader); budget > 0 && n > budget {
		keys := make([]string, len(sorted))
		for i, r := range sorted {
			keys[i] = r.Key
		}
		return out, &BudgetError{Size: n, Budget: budget, Keys: keys}
	}
	return out, nil
}

func (s *Store) RenderCore(ctx context.Context, scopes []string, budget int) (string, error) {
	recs, err := s.Core(ctx, scopes)
	if err != nil {
		return "", err
	}
	return RenderCore(recs, budget)
}

func WriteFileAtomic(path string, data []byte) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	f, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*")
	if err != nil {
		return err
	}
	tmp := f.Name()
	if _, err := f.Write(data); err != nil {
		_ = f.Close()
		_ = os.Remove(tmp)
		return err
	}
	if err := f.Chmod(0o644); err != nil {
		_ = f.Close()
		_ = os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return os.Rename(tmp, path)
}

func (s *Store) WriteCore(ctx context.Context, path string) (int, error) {
	out, err := s.RenderCore(ctx, CoreScopes, CoreBudget)
	if err != nil {
		return 0, err
	}
	return utf8.RuneCountInString(out), WriteFileAtomic(path, []byte(out))
}

type Filter struct {
	Kinds     []Kind
	Scopes    []string
	Statuses  []Status
	AllStatus bool
	Core      *bool
}

func (s *Store) List(ctx context.Context, f Filter) ([]Record, error) {
	fl := Query{Kinds: f.Kinds, Scopes: f.Scopes, Statuses: f.Statuses, AllStatus: f.AllStatus}.filter()
	if f.Core != nil {
		fl.add("r.core = ?", boolInt(*f.Core))
	}
	where := "WHERE 1 = 1" + fl.sql() + " ORDER BY r.key"
	rows, err := s.loadWhere(ctx, s.db, where, fl.args...)
	if err != nil {
		return nil, err
	}
	out := make([]Record, len(rows))
	for i, r := range rows {
		out[i] = r.rec
	}
	return out, nil
}

func (s *Store) ListByTrigger(ctx context.Context, scopes []string) ([]Record, error) {
	return s.listByTrigger(ctx, Query{Scopes: scopes})
}

func (s *Store) listByTrigger(ctx context.Context, q Query) ([]Record, error) {
	f := q.filter()
	f.add("EXISTS (SELECT 1 FROM triggers t WHERE t.record_id = r.id)")
	rows, err := s.loadWhere(ctx, s.db, "WHERE 1 = 1"+f.sql()+" ORDER BY r.key", f.args...)
	if err != nil {
		return nil, err
	}
	out := make([]Record, len(rows))
	for i, r := range rows {
		out[i] = r.rec
	}
	return out, nil
}

type TriggerHit struct {
	Record  Record  `json:"record"`
	Trigger Trigger `json:"trigger"`
}

func (s *Store) MatchTriggers(ctx context.Context, tool, subject string, scopes []string) ([]TriggerHit, error) {
	return s.matchTriggers(ctx, tool, subject, Query{Scopes: scopes})
}

func (s *Store) matchTriggers(ctx context.Context, tool, subject string, q Query) ([]TriggerHit, error) {
	recs, err := s.listByTrigger(ctx, q)
	if err != nil {
		return nil, err
	}
	var out []TriggerHit
	for _, r := range recs {
		for _, t := range r.Triggers {
			toolRe, err := regexp.Compile(`^(?:` + t.Tool + `)$`)
			if err != nil || !toolRe.MatchString(tool) {
				continue
			}
			re, err := regexp.Compile(t.Regex)
			if err != nil || !re.MatchString(subject) {
				continue
			}
			out = append(out, TriggerHit{Record: r, Trigger: t})
			break
		}
	}
	return out, nil
}
